import {renderRichText,insertRichTextMarker} from './cms-rich-text.mjs';
const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)];
const login=$('[data-login]'),app=$('[data-app]'),status=$('[data-status]'),preview=$('[data-preview]');
let pageOptions=[];
let autoSaveTimer=0;
const modules={events:{title:'Eventos',url:'index.html#calendario',description:'Gestionar calendario, carteles, rutas y consultar asistentes.'},members:{title:'Socios y usuarios',url:'garaje.html#gestion',description:'Gestionar fichas del garaje y revisar solicitudes de miembros.'},collaborators:{title:'Colaboradores',url:'colaboradores.html#gestion',description:'Editar listas, empresas, perfiles y enlaces.'},social:{title:'Redes sociales',url:'redes-sociales.html#gestion',description:'Gestionar perfiles y enlaces sociales. La publicación automática requiere una integración externa autorizada.'}};
const api=async(path,options={})=>{const response=await fetch('/api/'+path,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})},cache:'no-store'});let data={};try{data=await response.json();}catch{}if(response.status===401){app.hidden=true;login.hidden=false;}if(!response.ok)throw new Error(data.error||'No se pudo completar la operación.');return data;};
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateTime=seconds=>seconds?new Intl.DateTimeFormat('es-ES',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Madrid'}).format(new Date(seconds*1000)):'—';
const pretty=value=>Number(value||0).toLocaleString('es-ES');
function setStatus(message,element=status){if(element)element.textContent=message;}
function show(view){$$('[data-view]').forEach(section=>section.hidden=(section.dataset.view!==view));$$('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===view));const module=modules[view];if(module){$('[data-view="workspace"]').hidden=false;$$('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===view));$('[data-view-title]').textContent=module.title;$('[data-workspace-description]').textContent=module.description;$('[data-workspace-open]').href=module.url;const frame=$('[data-workspace]');if(frame.dataset.current!==module.url){frame.dataset.current=module.url;frame.src=module.url;}}else $('[data-view-title]').textContent=({dashboard:'Panel principal',content:'Contenido y páginas',news:'Noticias',appearance:'Apariencia',seo:'SEO y posicionamiento',communications:'Comunicaciones',security:'Seguridad',advanced:'Configuración avanzada'})[view]||view;}
async function refreshDashboard(){try{const d=await api('cms/admin/dashboard');$('[data-stat-views]').textContent=pretty(d.analytics?.views);$('[data-stat-visitors]').textContent=pretty(d.analytics?.visitors)+' visitantes';$('[data-stat-members]').textContent=pretty(d.members);$('[data-stat-news]').textContent=pretty(d.news);$('[data-stat-events]').textContent=pretty(d.events);$('[data-latest-news]').innerHTML=d.latestNews.length?d.latestNews.map(n=>`<li><strong>${escapeHtml(n.title)}</strong><small>${escapeHtml(n.category)} · ${dateTime(n.updated_at)}</small></li>`).join(''):'<li>No hay noticias todavía.</li>';$('[data-upcoming-events]').innerHTML=d.upcoming.length?d.upcoming.map(e=>`<li><strong>${escapeHtml(e.title)}</strong><small>${escapeHtml(e.event_date)} · ${escapeHtml(e.location)}</small></li>`).join(''):'<li>No hay eventos próximos.</li>';$('[data-recent-activity]').innerHTML=d.activity.length?d.activity.map(a=>`<tr><td>${dateTime(a.created_at)}</td><td>${escapeHtml(a.method)} ${escapeHtml(a.route)}</td><td>${escapeHtml(a.status||'en curso')}</td></tr>`).join(''):'<tr><td colspan="3">Todavía no hay operaciones registradas.</td></tr>';}catch(error){setStatus(error.message);}}
async function fillPageOptions(){try{const response=await fetch('cms-pages.json',{cache:'no-store'});pageOptions=(await response.json()).map(item=>[item.key,item.label]);}catch{pageOptions=[['index','Inicio']];}const options=pageOptions.map(([key,label])=>`<option value="${escapeHtml(key)}">${escapeHtml(label)}</option>`).join('');$('[data-content-page]').innerHTML=options;$('[data-seo-page]').innerHTML=options;}
function contentPageUrl(){const page=$('[data-content-page]').value;return page==='index'?'index.html':page+'.html';}
function refreshPreview(){const target=contentPageUrl(),url=new URL(target,location.href);url.searchParams.set('cms-preview','1');url.searchParams.set('v',String(Date.now()));preview.src=url.href;}
function cssSelector(element){if(element.id)return '#'+CSS.escape(element.id);const parts=[];let node=element;while(node&&node.nodeType===1&&node!==document){let part=node.localName;if(node.parentElement){const same=[...node.parentElement.children].filter(child=>child.localName===node.localName);if(same.length>1)part+=`:nth-of-type(${same.indexOf(node)+1})`;}parts.unshift(part);node=node.parentElement;}return parts.join(' > ');}
function pickable(){try{const doc=preview.contentDocument;if(!doc)throw Error('La vista previa todavía está cargando.');setStatus('Pulsa un elemento de la vista previa para elegirlo.');const handler=event=>{event.preventDefault();event.stopImmediatePropagation();doc.removeEventListener('click',handler,true);const element=event.target.closest('a,button,img,video,h1,h2,h3,p,section,figure,span');if(!element){setStatus('Elige un texto, botón, imagen o vídeo.');return;}doc.querySelectorAll('[data-cms-selected]').forEach(el=>{el.style.outline='';delete el.dataset.cmsSelected;});element.dataset.cmsSelected='1';element.style.outline='3px solid #74e554';const form=$('[data-content-form]');form.elements.selector.value=cssSelector(element);form.elements.label.value=(element.textContent||element.alt||element.getAttribute('aria-label')||element.localName).trim().slice(0,100);const kind=['img','video'].includes(element.localName)?'image':element.localName==='a'?'link':'text';form.elements.contentType.value=kind;form.elements.value.value=kind==='image'?element.getAttribute('src')||'':kind==='link'?element.getAttribute('href')||'':(element.textContent||'').trim();setStatus('Elemento seleccionado. Guarda como borrador o publica cuando estés listo.');};doc.addEventListener('click',handler,true);}catch(error){setStatus(error.message);}}
async function loadContent(){try{const data=await api('cms/admin/content');const page=$('[data-content-page]').value,items=data.filter(item=>item.page_key===page);$('[data-content-list]').innerHTML=items.length?items.map(item=>`<article class="content-row"><div><strong>${escapeHtml(item.label)}</strong><small>${escapeHtml(item.state)} · ${escapeHtml(item.content_type)} · v${item.version}</small><small>${escapeHtml(item.selector)}</small></div><div class="row-actions"><button type="button" data-edit-content="${item.id}">Editar</button><button type="button" data-history-content="${item.id}">Historial</button><button type="button" data-archive-content="${item.id}" data-version="${item.version}">Archivar</button></div></article>`).join(''):'<p>No hay elementos administrados para esta página.</p>';for(const button of $$('[data-edit-content]'))button.onclick=()=>{const item=items.find(entry=>entry.id===button.dataset.editContent);const form=$('[data-content-form]');form.elements.id.value=item.id;form.elements.expectedVersion.value=item.version;form.elements.label.value=item.label;form.elements.selector.value=item.selector;form.elements.contentType.value=item.content_type;form.elements.value.value=item.draft_value;form.elements.state.value=item.state==='scheduled'?'draft':item.state;};for(const button of $$('[data-history-content]'))button.onclick=()=>showHistory(button.dataset.historyContent);for(const button of $$('[data-archive-content]'))button.onclick=async()=>{if(!confirm('¿Archivar este elemento? Su historial se conservará y se podrá recuperar.'))return;try{await api(`cms/admin/content/${button.dataset.archiveContent}?version=${button.dataset.version}`,{method:'DELETE'});await loadContent();refreshPreview();setStatus('Elemento archivado; el historial se conserva.');}catch(error){setStatus(error.message);}};}catch(error){setStatus(error.message);}}
async function showHistory(itemId){try{const rows=await api(`cms/admin/content/${itemId}/versions`);const box=$('[data-content-list]');box.innerHTML=`<button type="button" data-back-content>← Volver al contenido</button>`+rows.map(row=>`<article class="content-row"><div><strong>Versión ${row.version}</strong><small>${escapeHtml(row.action)} · ${dateTime(row.created_at)}</small></div><button type="button" data-restore-version="${row.id}">Recuperar como borrador</button></article>`).join('');$('[data-back-content]').onclick=loadContent;for(const button of $$('[data-restore-version]'))button.onclick=async()=>{try{await api(`cms/admin/versions/${button.dataset.restoreVersion}/restore`,{method:'POST',body:'{}'});await loadContent();setStatus('Versión recuperada como borrador.');}catch(error){setStatus(error.message);}};}catch(error){setStatus(error.message);}}
async function saveContent(event){event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form));const state=data.state==='scheduled'?'scheduled':data.state;let publishAt=null;if(state==='scheduled'){publishAt=Math.floor(new Date(data.publishAt).getTime()/1000);if(!publishAt)return setStatus('Indica la fecha y hora de publicación.');}const body={page:$('[data-content-page]').value,label:data.label,selector:data.selector,contentType:data.contentType,value:data.value,state,publishAt,expectedVersion:Number(data.expectedVersion)||0};try{const result=await api(data.id?'cms/admin/content/'+data.id:'cms/admin/content',{method:'POST',body:JSON.stringify(body)});form.elements.id.value=result.id;form.elements.expectedVersion.value=result.version;await loadContent();refreshPreview();setStatus(state==='published'?'Cambios publicados.':state==='scheduled'?'Publicación programada.':'Borrador guardado.');}catch(error){setStatus(error.message);}}
async function loadMedia(){try{const files=await api('cms/admin/media');$('[data-media-list]').innerHTML=files.length?files.map(file=>`<article class="media-item">${file.content_type.startsWith('image/')?`<img src="/api/cms/media/${file.id}" alt="">`:`<video src="/api/cms/media/${file.id}" controls preload="metadata"></video>`}<small>${escapeHtml(file.content_type)} · ${pretty(Math.ceil(file.size/1024))} KB</small><button type="button" data-copy-media="/api/cms/media/${file.id}">Copiar dirección</button></article>`).join(''):'<p>No hay archivos en el gestor multimedia.</p>';for(const button of $$('[data-copy-media]'))button.onclick=async()=>{await navigator.clipboard.writeText(new URL(button.dataset.copyMedia,location.href).href);setStatus('Dirección copiada al portapapeles.');};}catch(error){setStatus(error.message);}}
async function loadSettings(){try{const data=await api('cms/admin/settings');for(const key of ['appearance','seo','general','communications']){const form=$(`[data-settings-form="${key}"]`);if(form)for(const input of form.elements)if(input.name&&data[key]?.[input.name]!==undefined)input.value=data[key][input.name];}const features=$('[data-features-form]'),names={news:'Noticias',events:'Eventos',garage:'Garaje',gallery:'Galería',collaborators:'Colaboradores',social:'Redes sociales',market:'Mercadillo',bricos:'Bricos'};features.innerHTML=Object.entries(names).map(([key,label])=>`<label><input type="checkbox" name="${key}" ${data.features[key]?'checked':''}> ${label}</label>`).join('');fillPageSeo(data.seo);}catch(error){setStatus(error.message);}}
async function loadSettingsHistory(key){try{const rows=await api(`cms/admin/settings/${key}/versions`),list=$(`[data-settings-history-list="${key}"]`);list.hidden=false;list.innerHTML=rows.length?rows.map(row=>{let value='';try{value=JSON.stringify(JSON.parse(row.value_json),null,2);}catch{}return `<article class="content-row"><div><strong>${escapeHtml(key)} · ${dateTime(row.created_at)}</strong><pre>${escapeHtml(value)}</pre></div><button type="button" data-restore-setting="${row.id}" data-setting-key="${key}">Restaurar</button></article>`;}).join(''):'<p>Aún no hay versiones guardadas.</p>';for(const button of $$('[data-restore-setting]'))button.onclick=async()=>{if(!confirm('¿Restaurar estos ajustes? Se guardará otra versión con el estado anterior.'))return;try{await api(`cms/admin/settings-versions/${button.dataset.restoreSetting}/restore`,{method:'POST',body:'{}'});await loadSettings();await loadSettingsHistory(button.dataset.settingKey);refreshPreview();setStatus('Ajustes restaurados y versionados.');}catch(error){setStatus(error.message);}};}catch(error){setStatus(error.message);}}
function fillPageSeo(seo){const form=$('[data-settings-form="seo"]'),page=seo?.pages?.[$('[data-seo-page]').value]||{};form.elements.pageTitle.value=page.title||'';form.elements.pageDescription.value=page.description||'';form.elements.pageRobots.value=page.robots||'index,follow';form.elements.pageShareImage.value=page.shareImage||'';}
async function saveSettings(form){const key=form.dataset.settingsForm,value=Object.fromEntries([...new FormData(form)]);for(const input of form.querySelectorAll('input'))if(input.type==='color')value[input.name]=input.value;try{if(key==='seo'){const existing=await api('cms/admin/settings'),pages={...(existing.seo?.pages||{})},slug=$('[data-seo-page]').value;pages[slug]={title:value.pageTitle,description:value.pageDescription,robots:value.pageRobots,shareImage:value.pageShareImage};const seo={title:value.title,description:value.description,robots:value.robots,shareImage:value.shareImage,pages};await api('cms/admin/settings',{method:'POST',body:JSON.stringify({key,value:seo})});}else await api('cms/admin/settings',{method:'POST',body:JSON.stringify({key,value})});setStatus('Configuración guardada y versionada.');if(key==='appearance'||key==='seo'||key==='general')refreshPreview();}catch(error){setStatus(error.message);}}
async function loadAudit(){try{const rows=await api('cms/admin/audit');$('[data-audit-log]').innerHTML=rows.length?rows.map(row=>`<tr><td>${dateTime(row.created_at)}</td><td>${row.admin_id===document.body.dataset.ownerId?'Raúl (propietario)':escapeHtml(row.admin_id||'Sin sesión')}</td><td>${escapeHtml(row.method)}</td><td>${escapeHtml(row.route)}</td><td>${escapeHtml(row.status)}</td></tr>`).join(''):'<tr><td colspan="5">Sin accesos registrados.</td></tr>';}catch(error){setStatus(error.message,$('[data-security-status]'));}}
async function loadPages(){try{const pages=await api('cms/admin/pages');$('[data-custom-pages]').innerHTML=pages.length?pages.map(page=>`<article class="content-row"><div><strong>${escapeHtml(page.draft_title)}</strong><small>/${escapeHtml(page.slug)} · ${escapeHtml(page.state)} · v${page.version}</small></div><div class="row-actions"><button type="button" data-edit-page="${escapeHtml(page.slug)}">Editar</button><button type="button" data-history-page="${escapeHtml(page.slug)}">Historial</button><a href="pagina.html?slug=${encodeURIComponent(page.slug)}&cms-preview=1" target="_blank" rel="noopener">Previsualizar ↗</a></div></article>`).join(''):'<p>Aún no hay páginas personalizadas.</p>';for(const button of $$('[data-edit-page]'))button.onclick=()=>{const page=pages.find(item=>item.slug===button.dataset.editPage),form=$('[data-page-form]');form.elements.expectedVersion.value=page.version;form.elements.slug.value=page.slug;form.elements.slug.readOnly=true;form.elements.title.value=page.draft_title;form.elements.description.value=page.draft_description;form.elements.body.value=page.draft_body;renderRichText($('[data-page-preview]'),page.draft_body);form.elements.state.value=page.state==='scheduled'?'draft':page.state;};for(const button of $$('[data-history-page]'))button.onclick=()=>showPageHistory(button.dataset.historyPage);}catch(error){setStatus(error.message);}}
async function showPageHistory(slug){try{const rows=await api(`cms/admin/pages/${slug}/versions`),list=$('[data-custom-pages]');list.innerHTML=`<button type="button" data-page-history-back>← Volver a páginas</button>`+rows.map(row=>`<article class="content-row"><div><strong>Versión ${row.version}</strong><small>${dateTime(row.created_at)}</small></div><button type="button" data-restore-page-version="${row.id}">Recuperar como borrador</button></article>`).join('');$('[data-page-history-back]').onclick=loadPages;for(const button of $$('[data-restore-page-version]'))button.onclick=async()=>{try{await api(`cms/admin/page-versions/${button.dataset.restorePageVersion}/restore`,{method:'POST',body:'{}'});await loadPages();setStatus('Página recuperada como borrador.');}catch(error){setStatus(error.message);}};}catch(error){setStatus(error.message);}}
async function loadBackup(){try{const backup=await api('cms/admin/backup');const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='octavia-cms-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href);setStatus('Copia de seguridad del CMS descargada.');}catch(error){setStatus(error.message,$('[data-backup-status]'));}}
async function loadNews(){try{const [items,media]=await Promise.all([api('cms/admin/news'),api('cms/admin/media')]);const select=$('[data-news-form] [name=mediaId]'),selected=select.value;select.innerHTML='<option value="">Sin multimedia</option>'+media.map(item=>`<option value="${item.id}">${escapeHtml(item.content_type)} · ${escapeHtml(item.caption||item.id.slice(0,8))}</option>`).join('');if([...select.options].some(option=>option.value===selected))select.value=selected;const list=$('[data-news-list]');list.innerHTML=items.length?items.map(item=>`<article class="content-row"><div><strong>${escapeHtml(item.draft_title)}</strong><small>${escapeHtml(item.draft_category)} · ${escapeHtml(item.state)} · v${item.version}</small><small>${item.draft_featured?'Destacada · ':''}${item.draft_media_type?escapeHtml(item.draft_media_type):'Sin multimedia'}</small></div><div class="row-actions"><button type="button" data-edit-news="${item.id}">Editar</button><button type="button" data-news-history="${item.id}">Historial</button><button type="button" data-archive-news="${item.id}" data-version="${item.version}">Archivar</button></div></article>`).join(''):'<p>No hay noticias en el CMS todavía.</p>';for(const button of $$('[data-edit-news]'))button.onclick=()=>{const item=items.find(row=>row.id===button.dataset.editNews),form=$('[data-news-form]');form.elements.id.value=item.id;form.elements.expectedVersion.value=item.version;form.elements.title.value=item.draft_title;form.elements.category.value=item.draft_category;form.elements.body.value=item.draft_body;renderRichText($('[data-news-preview]'),item.draft_body);form.elements.linkUrl.value=item.draft_link_url;form.elements.mediaId.value=item.draft_media_id;form.elements.expiresOn.value=item.draft_expires_on;form.elements.featured.checked=Boolean(item.draft_featured);form.elements.state.value=item.state==='scheduled'?'draft':item.state;form.elements.publishAt.value=item.publish_at?new Date(item.publish_at*1000).toISOString().slice(0,16):'';$('[data-news-form-title]').textContent='Editar noticia';};for(const button of $$('[data-news-history]'))button.onclick=()=>showNewsHistory(button.dataset.newsHistory);for(const button of $$('[data-archive-news]'))button.onclick=async()=>{if(!confirm('¿Archivar esta noticia? Se conservará en el historial y en las copias.'))return;try{await api(`cms/admin/news/${button.dataset.archiveNews}?version=${button.dataset.version}`,{method:'DELETE'});await loadNews();setStatus('Noticia archivada.');}catch(error){setStatus(error.message);}};}catch(error){setStatus(error.message,$('[data-news-editor-status]'));}}
async function showNewsHistory(newsId){try{const rows=await api(`cms/admin/news/${newsId}/versions`),list=$('[data-news-list]');list.innerHTML='<button type="button" data-news-history-back>← Volver a noticias</button>'+rows.map(row=>`<article class="content-row"><div><strong>Versión ${row.version}</strong><small>${escapeHtml(row.action)} · ${dateTime(row.created_at)}</small></div><button type="button" data-restore-news="${row.id}">Recuperar como borrador</button></article>`).join('');$('[data-news-history-back]').onclick=loadNews;for(const button of $$('[data-restore-news]'))button.onclick=async()=>{try{await api(`cms/admin/news-versions/${button.dataset.restoreNews}/restore`,{method:'POST',body:'{}'});await loadNews();setStatus('Versión recuperada como borrador.');}catch(error){setStatus(error.message);}};}catch(error){setStatus(error.message);}}

await fillPageOptions();$('[data-seo-page]').onchange=async()=>{try{const data=await api('cms/admin/settings');fillPageSeo(data.seo);}catch(error){setStatus(error.message);}};
const activation=new URLSearchParams(location.hash.slice(1)).get('activar');if(location.hash)history.replaceState(null,'',location.pathname+location.search);
if(activation){$('[data-login-title]').textContent='Activar acceso privado';$('[data-setup-copy]').hidden=false;login.elements.password.autocomplete='new-password';}
async function enter(owner){document.body.dataset.ownerId=owner.id;login.hidden=true;app.hidden=false;$('[data-owner-label]').textContent='Raúl · propietario único';$('[data-logout]').hidden=false;await Promise.all([refreshDashboard(),loadContent(),loadMedia(),loadSettings(),loadPages(),loadAudit(),loadNews()]);show('dashboard');}
login.addEventListener('submit',async event=>{event.preventDefault();const button=login.querySelector('button');button.disabled=true;setStatus('Comprobando acceso…');try{const data=Object.fromEntries(new FormData(login));const owner=await api(activation?'admin/setup':'admin/login',{method:'POST',body:JSON.stringify(activation?{...data,key:activation}:data)});await enter(owner);login.reset();}catch(error){setStatus(error.message);}finally{button.disabled=false;}});
try{await enter(await api('admin/session'));}catch(error){login.hidden=false;$('[data-owner-label]').textContent='Sesión no iniciada';if(!activation)setStatus(error.message);}
$$('[data-tab]').forEach(button=>button.onclick=()=>{show(button.dataset.tab);if(button.dataset.tab==='dashboard')refreshDashboard();if(button.dataset.tab==='security')loadAudit();if(button.dataset.tab==='news')loadNews();});$$('[data-open-tab]').forEach(button=>button.onclick=()=>show(button.dataset.openTab));
$$('[data-logout]').forEach(button=>button.onclick=async()=>{try{await api('admin/logout',{method:'POST',body:'{}'});app.hidden=true;login.hidden=false;$('[data-owner-label]').textContent='Sesión cerrada';}catch(error){setStatus(error.message);}});
$$('[data-content-page]').forEach(select=>select.onchange=()=>{refreshPreview();loadContent();});$('[data-pick-target]').onclick=pickable;$('[data-reload-preview]').onclick=refreshPreview;$('[data-content-form]').addEventListener('submit',saveContent);$('[data-new-content]').onclick=()=>{$('[data-content-form]').reset();$('[data-content-form]').elements.id.value='';$('[data-content-form]').elements.expectedVersion.value='';};$('[data-content-form] [name=state]').onchange=event=>{$('[data-schedule-field]').hidden=event.target.value!=='scheduled';};
$$('[data-settings-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();saveSettings(form);}));$('[data-features-form]').addEventListener('submit',event=>{event.preventDefault();});
$$('[data-settings-history]').forEach(button=>button.addEventListener('click',()=>loadSettingsHistory(button.dataset.settingsHistory)));
document.addEventListener('change',async event=>{if(event.target.closest('[data-features-form]')){const form=event.target.closest('[data-features-form]'),value=Object.fromEntries([...form.querySelectorAll('input[type=checkbox]')].map(input=>[input.name,input.checked]));try{await api('cms/admin/settings',{method:'POST',body:JSON.stringify({key:'features',value})});setStatus('Funciones públicas actualizadas.');}catch(error){setStatus(error.message);}}});
$('[data-media-form]').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{await api('cms/admin/media',{method:'POST',body:form});event.currentTarget.reset();setStatus('Archivo multimedia subido.',$('[data-media-status]'));await loadMedia();}catch(error){setStatus(error.message,$('[data-media-status]'));}});
$('[data-news-form]').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form));data.featured=form.elements.featured.checked;data.expectedVersion=Number(data.expectedVersion)||0;data.mediaType=data.mediaId?form.elements.mediaId.selectedOptions[0]?.textContent.split(' · ')[0]:'';if(data.state==='scheduled'){data.publishAt=Math.floor(new Date(data.publishAt).getTime()/1000);if(!data.publishAt)return setStatus('Indica la fecha y hora de publicación.',$('[data-news-editor-status]'));}else data.publishAt=null;try{const result=await api('cms/admin/news',{method:'POST',body:JSON.stringify(data)});form.elements.id.value=result.id;form.elements.expectedVersion.value=result.version;setStatus(result.state==='published'?'Noticia publicada.':result.state==='scheduled'?'Noticia programada.':'Borrador guardado.',$('[data-news-editor-status]'));await Promise.all([loadNews(),refreshDashboard()]);}catch(error){setStatus(error.message,$('[data-news-editor-status]'));}});$('[data-news-new]').onclick=()=>{const form=$('[data-news-form]');form.reset();form.elements.id.value='';form.elements.expectedVersion.value='';form.elements.category.value='Noticias';$('[data-news-form-title]').textContent='Nueva noticia';};$('[data-news-form] [name=state]').onchange=event=>{$('[data-news-schedule]').hidden=event.target.value!=='scheduled';};
$('[data-page-form]').addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));data.expectedVersion=Number(data.expectedVersion)||0;try{const page=await api('cms/admin/pages',{method:'POST',body:JSON.stringify(data)});event.currentTarget.elements.expectedVersion.value=page.version;event.currentTarget.elements.slug.readOnly=true;setStatus(page.state==='published'?'Página publicada en pagina.html?slug='+page.slug:'Borrador guardado.',$('[data-page-result]'));await loadPages();}catch(error){setStatus(error.message,$('[data-page-result]'));}});$('[data-new-page]').onclick=()=>{const form=$('[data-page-form]');form.reset();form.elements.expectedVersion.value='';form.elements.slug.readOnly=false;};
$('[data-backup-download]').onclick=loadBackup;$('[data-backup-restore]').onclick=async()=>{const file=$('[data-backup-file]').files[0];if(!file)return setStatus('Selecciona primero una copia JSON.',$('[data-backup-status]'));if(!confirm('¿Restaurar esta copia? Recuperará contenido CMS, ajustes y visibilidad de fichas incluidas. No eliminará filas ni archivos multimedia.'))return;try{const snapshot=JSON.parse(await file.text());await api('cms/admin/backup',{method:'POST',body:JSON.stringify(snapshot)});setStatus('Copia restaurada. Los cambios quedaron registrados en las tablas del CMS.',$('[data-backup-status]'));await Promise.all([loadContent(),loadSettings(),loadPages()]);}catch(error){setStatus(error.message,$('[data-backup-status]'));}};
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='cms-preview-updated')return;refreshPreview();});
document.addEventListener('input',event=>{const form=event.target.closest('[data-content-form],[data-news-form],[data-page-form]');if(!form||form.elements.state?.value!=='draft')return;if(form.matches('[data-news-form]')&&!form.elements.title.value.trim())return;if(form.matches('[data-page-form]')&&(!form.elements.slug.value.trim()||!form.elements.title.value.trim()))return;clearTimeout(autoSaveTimer);setStatus('Borrador: guardado automático en curso…');autoSaveTimer=setTimeout(()=>form.requestSubmit(),1400);});
document.addEventListener('input',event=>{if(event.target.matches('[data-news-form] [name=body]'))renderRichText($('[data-news-preview]'),event.target.value);if(event.target.matches('[data-page-form] [name=body]'))renderRichText($('[data-page-preview]'),event.target.value);});
document.addEventListener('click',event=>{const button=event.target.closest('[data-rich-before]');if(!button)return;const target=button.dataset.richTarget==='news'?'[data-news-form] [name=body]':'[data-page-form] [name=body]',textarea=$(target);insertRichTextMarker(textarea,button.dataset.richBefore,button.dataset.richAfter||'');});
